// Normalize webhook / manual / schedule into one apply-all or watch payload.
// Input names match .github/workflows/apply-all.yml and Pages run_controls.js.

const root = $input.first().json || {};
const body = root.body && typeof root.body === 'object' ? root.body : root;
const query = root.query && typeof root.query === 'object' ? root.query : {};
const src = { ...query, ...body };

function asBool(v, defaultTrue) {
  if (v === undefined || v === null || v === '') return defaultTrue;
  if (typeof v === 'boolean') return v;
  const s = String(v).trim().toLowerCase();
  if (['1', 'true', 'yes', 'y', 'on'].includes(s)) return true;
  if (['0', 'false', 'no', 'n', 'off'].includes(s)) return false;
  return defaultTrue;
}

function asUser(v) {
  const s = String(v || 'both').trim().toLowerCase();
  if (s === 'ravi' || s === 'jaya' || s === 'both') return s;
  return 'both';
}

function asLimit(v) {
  let n = parseInt(v, 10);
  if (!Number.isFinite(n) || n < 1) n = 50;
  if (n > 100) n = 100;
  return String(n);
}

const actionRaw = String(src.action || src.workflow || 'apply-all').trim().toLowerCase();
const action = actionRaw === 'watch' || actionRaw === 'watch-jobs' ? 'watch' : 'apply-all';

const owner = String($env.GITHUB_OWNER || 'raviacn95').trim();
const repo = String($env.GITHUB_REPO || 'ConsultingCompanyAutomation').trim();
const ref = String($env.GITHUB_REF || 'main').trim();
const token = String($env.GITHUB_TOKEN || '').trim();
if (!token) {
  throw new Error('GITHUB_TOKEN env is missing. Set a PAT with repo + actions in n8n environment.');
}

const user = asUser(src.user);
const mail = asBool(src.mail, true);
const easy_apply = asBool(src.easy_apply, true);
const easy_submit = asBool(src.easy_submit, true);
const easy_limit = asLimit(src.easy_limit);
const also_watch = asBool(src.also_watch, false);
const local_repo = String(src.local_repo || 'C:\\Users\\ravir\\ConsultingCompanyAutomation');

const pollMax = Math.max(1, parseInt($env.POLL_MAX_ATTEMPTS || '36', 10) || 36);
const pollSeconds = Math.max(5, parseInt($env.POLL_SECONDS || '20', 10) || 20);

const workflowFile = action === 'watch' ? 'watch-jobs.yml' : 'apply-all.yml';

let inputs;
if (action === 'watch') {
  inputs = {
    mail: mail ? 'true' : 'false',
    local_repo,
  };
} else {
  inputs = {
    mail: mail ? 'true' : 'false',
    easy_apply: easy_apply ? 'true' : 'false',
    easy_submit: easy_submit ? 'true' : 'false',
    easy_limit,
    user,
    local_repo,
  };
}

const dispatchedAt = new Date().toISOString();

return [{
  json: {
    action,
    workflowFile,
    owner,
    repo,
    ref,
    token,
    inputs,
    user,
    also_watch,
    dispatchedAt,
    pollAttempt: 0,
    pollMax,
    pollSeconds,
    notifyUrl: String($env.NOTIFY_WEBHOOK_URL || '').trim(),
    pagesAutoAppliedUrl: 'https://raviacn95.github.io/ConsultingCompanyAutomation/auto_applied_jobs.js',
    actionsRunsUrl: `https://github.com/${owner}/${repo}/actions/workflows/${workflowFile}`,
  },
}];

const prev = $('Normalize inputs').first().json;
const res = $input.first().json;
const statusCode = res.statusCode ?? res.status ?? 0;
const ok = statusCode === 204 || statusCode === 200;

if (!ok) {
  const body = res.body || res;
  const msg = (body && body.message) ? body.message : JSON.stringify(body).slice(0, 300);
  throw new Error(`GitHub dispatch failed HTTP ${statusCode}: ${msg}`);
}

return [{
  json: {
    ...prev,
    dispatchOk: true,
    dispatchStatus: statusCode,
  },
}];

const base = $('Confirm dispatch 204').first().json;
// HTTP Poll replaces item data — recover attempt count from prior runs of this node.
let prevAttempt = 0;
try {
  const prior = $('Evaluate run status').all();
  if (prior && prior.length) {
    prevAttempt = Math.max(...prior.map((i) => Number(i.json.pollAttempt || 0)));
  }
} catch (_) {
  prevAttempt = 0;
}
const pollAttempt = prevAttempt + 1;
const pollMax = Number(base.pollMax || 36);
const dispatchedMs = Date.parse(base.dispatchedAt) - 60000;

const payload = $input.first().json;
const runs = (payload.workflow_runs || []);

let run = null;
for (const r of runs) {
  const created = Date.parse(r.created_at || r.updated_at || 0);
  if (Number.isFinite(created) && created >= dispatchedMs) {
    run = r;
    break;
  }
}
if (!run && runs.length) run = runs[0];

const status = run ? (run.status || '') : 'unknown';
const conclusion = run ? (run.conclusion || null) : null;
const completed = status === 'completed';
const timedOut = !completed && pollAttempt >= pollMax;

let outcome = 'running';
if (completed && conclusion === 'success') outcome = 'success';
else if (completed) outcome = 'failure';
else if (timedOut) outcome = 'timeout';

return [{
  json: {
    ...base,
    pollAttempt,
    pollMax,
    runId: run ? run.id : null,
    runNumber: run ? run.run_number : null,
    runUrl: run ? run.html_url : base.actionsRunsUrl,
    runStatus: status,
    runConclusion: conclusion,
    completed,
    timedOut,
    outcome,
    done: completed || timedOut,
  },
}];

const base = $('Evaluate run status').first().json;
const raw = $input.first().json;
let text = '';
if (typeof raw === 'string') text = raw;
else if (raw.data != null) text = String(raw.data);
else if (raw.body != null) text = typeof raw.body === 'string' ? raw.body : JSON.stringify(raw.body);
else text = JSON.stringify(raw);

let auto = null;
try {
  const m = text.match(/window\.AUTO_APPLIED_JOBS\s*=\s*(\{[\s\S]*?\})\s*;/);
  if (m) auto = JSON.parse(m[1]);
} catch (e) {
  auto = null;
}

const byUser = (auto && auto.by_user) || {};
const byMethod = (auto && auto.by_method) || {};
const total = auto && auto.total != null ? auto.total : '?';
const ravi = byUser.ravi != null ? byUser.ravi : '?';
const jaya = byUser.jaya != null ? byUser.jaya : '?';
const emailN = byMethod.email != null ? byMethod.email : '?';
const easyN = byMethod.easy_apply != null ? byMethod.easy_apply : '?';

const emoji = base.outcome === 'success' ? '✅' : base.outcome === 'timeout' ? '⏱️' : '❌';
const title = `${emoji} ${base.workflowFile} · ${base.outcome}`;
const lines = [
  title,
  `user=${base.user} · action=${base.action}`,
  `inputs: ${JSON.stringify(base.inputs)}`,
  `run: #${base.runNumber || '?'} ${base.runStatus}/${base.runConclusion || 'n/a'}`,
  `link: ${base.runUrl}`,
  `auto-applied (Pages): total=${total} · ravi=${ravi} · jaya=${jaya} · email=${emailN} · easy=${easyN}`,
  auto && auto.generated_at ? `auto-applied generated_at=${auto.generated_at}` : 'auto-applied: parse skipped or stale Pages cache',
];

const textMsg = lines.join('\n');

// Discord-compatible; Slack incoming webhooks also accept { text }.
const notifyBody = {
  content: textMsg.slice(0, 1900),
  text: textMsg.slice(0, 3900),
};

return [{
  json: {
    ...base,
    autoApplied: auto
      ? { total, by_user: byUser, by_method: byMethod, generated_at: auto.generated_at }
      : null,
    notifyBody,
    summaryText: textMsg,
    ok: base.outcome === 'success',
  },
}];

// Pass through summary whether or not notify ran.
const fromNotify = $input.first().json;
if (fromNotify.summaryText) return [{ json: fromNotify }];
return [{ json: $('Build summary + notify body').first().json }];
